L7_1 = "\227\129\157\227\130\140\227\130\136\227\130\138\227\131\170\227\130\179\227\131\170\227\130\185\227\129\175\239\188\159\227\128\128\227\129\130\227\129\174\228\186\186\227\129\140\232\168\177\229\143\175\227\129\153\227\130\139\227\129\175\227\129\154\227\129\170\227\129\132\227\130\147\227\129\160\227\129\145\227\129\169\227\128\130"
