L6_1.m_Talk_TWN = L7_1
L7_1 = "\224\185\129\224\184\165\224\185\137\224\184\167\224\185\132\224\184\165\224\185\130\224\184\132\224\184\163\224\184\180\224\184\170\224\184\165\224\185\136\224\184\176? \224\184\153\224\184\178\224\184\135\224\184\149\224\185\137\224\184\173\224\184\135\224\185\132\224\184\161\224\185\136\224\184\162\224\184\173\224\184\161\224\185\131\224\184\171\224\185\137\224\185\128\224\184\152\224\184\173\224\184\161\224\184\178\224\184\151\224\184\181\224\185\136\224\184\153\224\184\181\224\185\136\224\185\129\224\184\153\224\185\136\224\185\134"
